1	// Interaction measurements against a running production build (see scripts/perf-pages.mjs for setup).
2	//   node --env-file=.env scripts/perf-interactions.mjs <baseUrl> <label> [runs=3]
3	// Costs a few real chat answers (default OpenAI chat model) and, on builds with voice, one realtime transcription session.
4	//   panel      click on Ask Moneo until the panel dialog is open
5	//   chat       POST /api/chat with a simple question: response headers, first stream event, full answer
6	//   history    GET /api/conversations/:id (what loadConversation costs, and what a poll costs)
7	//   mic        tap on the mic until the recording view is ready (fake microphone; branches with voice only)
8	//   recording  long tasks (over 50 ms) and layout shift while 5 s of live transcription runs
9	//   polling    requests per 12 s with a request running in the background, a hidden tab, and nothing running
10	import { mkdirSync, writeFileSync } from "node:fs";
11	import { chromium } from "@playwright/test";
12	import postgres from "postgres";
13	
14	const [base, label, runsArg] = process.argv.slice(2);
15	if (!base || !label) throw new Error("usage: node scripts/perf-interactions.mjs <baseUrl> <label> [runs]");
16	const runs = Number(runsArg ?? 3);
17	const db = postgres(process.env.SUPABASE_DB_URL, { max: 1, onnotice: () => {} });
18	const [{ workspace_id: workspace }] = await db`select w.id as workspace_id from public.workspaces w join auth.users u on u.id=w.owner_id where u.email=${process.env.E2E_USER_EMAIL}`;
