export type Point = { x: number; y: number };
export type Box = { left: number; right: number; top: number; bottom: number };
export type DropSide = "on" | "before" | "after";

const contains = (box: Box, point: Point) => point.x >= box.left && point.x <= box.right && point.y >= box.top && point.y <= box.bottom;

/** How far a point is from a box: 0 inside it, so a gap or an empty stretch of a row belongs to the widget at its edge. */
export function distanceToBox(box: Box, point: Point) {
  const dx = Math.max(box.left - point.x, 0, point.x - box.right), dy = Math.max(box.top - point.y, 0, point.y - box.bottom);
  return Math.hypot(dx, dy);
}

/** Where a pointer sits relative to the nearest widget: on it, or in the empty space before or after it. */
export function dropSide(box: Box, point: Point): DropSide {
  if (contains(box, point)) return "on";
  return point.y > box.bottom || (point.x > box.right && point.y >= box.top) ? "after" : "before";
}

/** The order after dropping a widget: on another takes its place; beside another goes next to it. */
export function moveWidget(items: string[], active: string, over: string, side: DropSide) {
  const from = items.indexOf(active), to = items.indexOf(over);
  if (from < 0 || to < 0 || from === to) return items;
  const rest = items.filter(item => item !== active);
  const at = rest.indexOf(over);
  // On a widget means taking its slot, which lands after it when moving forward and before it when moving back.
  const index = side === "on" ? (from < to ? at + 1 : at) : side === "after" ? at + 1 : at;
  return [...rest.slice(0, index), active, ...rest.slice(index)];
}

import { describe, expect, it } from "vitest";
import { distanceToBox, dropSide, moveWidget } from "./home-grid-drop";

const box = { left: 100, right: 200, top: 100, bottom: 200 };

describe("dropSide", () => {
  it("is on the widget when the pointer is inside it", () => expect(dropSide(box, { x: 150, y: 150 })).toBe("on"));
  it("is after the widget in the empty space to its right", () => expect(dropSide(box, { x: 400, y: 150 })).toBe("after"));
  it("is after the widget below it", () => expect(dropSide(box, { x: 150, y: 400 })).toBe("after"));
  it("is before the widget above or to its left", () => {
    expect(dropSide(box, { x: 150, y: 50 })).toBe("before");
    expect(dropSide(box, { x: 50, y: 150 })).toBe("before");
  });
});

describe("distanceToBox", () => {
  it("is zero inside and measures from the nearest edge outside", () => {
    expect(distanceToBox(box, { x: 150, y: 150 })).toBe(0);
    expect(distanceToBox(box, { x: 230, y: 150 })).toBe(30);
  });
});

describe("moveWidget", () => {
  const items = ["a", "b", "c", "d"];
  it("takes the slot of the widget it lands on, either way", () => {
    expect(moveWidget(items, "a", "c", "on")).toEqual(["b", "c", "a", "d"]);
    expect(moveWidget(items, "d", "b", "on")).toEqual(["a", "d", "b", "c"]);
  });
  it("goes next to a widget when dropped in the space beside it", () => {
    expect(moveWidget(items, "d", "a", "after")).toEqual(["a", "d", "b", "c"]);
    expect(moveWidget(items, "a", "d", "after")).toEqual(["b", "c", "d", "a"]);
    expect(moveWidget(items, "d", "a", "before")).toEqual(["d", "a", "b", "c"]);
  });
  it("leaves the order alone for itself or unknown widgets", () => {
    expect(moveWidget(items, "a", "a", "on")).toBe(items);
    expect(moveWidget(items, "a", "z", "on")).toBe(items);
  });
});

