"use client";

import { startTransition, useActionState, useEffect, useRef, type ReactNode } from "react";
import type { SafeState } from "@/lib/safe-action";

/**
 * A form whose failure shows beside it and keeps what was typed; React's own form action would clear the fields either way.
 * Fields clear only after a save that went through.
 */
export function SafeForm({ action, className, children }: { action: (state: SafeState, form: FormData) => Promise<SafeState>; className?: string; children: ReactNode }) {
  const [state, submit, pending] = useActionState(action, {});
  const form = useRef<HTMLFormElement>(null);
  const wasPending = useRef(false);
  useEffect(() => {
    if (wasPending.current && !pending && !state.error) form.current?.reset();
    wasPending.current = pending;
  }, [pending, state.error]);
  return <form ref={form} className={className} onSubmit={event => {
    event.preventDefault();
    const data = new FormData(event.currentTarget);
    startTransition(() => submit(data));
  }}>
    <fieldset disabled={pending} className="contents">{children}</fieldset>
    {state.error && <p role="alert" className="basis-full text-sm text-danger sm:col-span-full">{state.error}</p>}
  </form>;
}

import { unstable_rethrow } from "next/navigation";
import { z } from "zod";
import { readableError } from "@/lib/ai/agent-apply";

export type SafeState = { error?: string };

/** Runs a form action so a refusal comes back as a message for the form, not the error page. Redirects still happen. */
export async function safely(form: FormData, action: (form: FormData) => Promise<unknown>): Promise<SafeState> {
  try {
    await action(form);
    return {};
  } catch (cause) {
    unstable_rethrow(cause);
    if (cause instanceof z.ZodError) return { error: cause.issues[0]?.message ?? "Check the form and try again" };
    return { error: readableError(cause) };
  }
}

import { expect, it, vi } from "vitest";
import { z } from "zod";
import { safely } from "./safe-action";

vi.mock("@/lib/ai/agent-apply", () => ({ readableError: (cause: unknown) => cause instanceof Error ? cause.message : "Could not save" }));

const form = new FormData();

it("returns nothing to show after a save", async () => {
  expect(await safely(form, async () => "saved")).toEqual({});
});

it("turns validation and refusals into a message for the form", async () => {
  const invalid = z.object({ name: z.string().min(1, "Enter a name") }).safeParse({ name: "" });
  expect(await safely(form, async () => { throw invalid.error; })).toEqual({ error: "Enter a name" });
  expect(await safely(form, async () => { throw new Error("Account not found"); })).toEqual({ error: "Account not found" });
});

it("lets a redirect through", async () => {
  const redirect = Object.assign(new Error("NEXT_REDIRECT"), { digest: "NEXT_REDIRECT;replace;/plan;307;" });
  await expect(safely(form, async () => { throw redirect; })).rejects.toBe(redirect);
});

import {readFileSync,writeFileSync} from "node:fs";
const read=p=>readFileSync(p,'utf8');
const addSafe=(p,names)=>{let s=read(p);const crlf=s.includes('\r\n');s=s.replace(/\r\n/g,'\n');
 const i=s.indexOf('"use server";');if(i<0)throw new Error(p);
 s=s.replace('"use server";\n','"use server";\n\nimport { safely, type SafeState } from "@/lib/safe-action";');
 s=s.trimEnd()+'\n\n'+names.map(n=>`export async function ${n}Safely(_state: SafeState, form: FormData) { return safely(form, ${n}); }`).join('\n')+'\n';
 writeFileSync(p,crlf?s.replace(/\n/g,'\r\n'):s);console.log('ok',p)};
addSafe('app/money/accounts/actions.ts',['addAccount','addOwnAccount']);
addSafe('app/plan/actions.ts',['createGoal','addAssumption']);
addSafe('app/plan/spending/actions.ts',['saveSpendingPlan']);
addSafe('app/money/wealth/actions.ts',['saveWealthItem']);
addSafe('app/plan/currency/actions.ts',['addFxRate','setDisplayCurrency']);
const forms=[['app/money/accounts/own-accounts.tsx',['addOwnAccount']],['app/money/accounts/page.tsx',['addAccount']],['app/money/wealth/form.tsx',['saveWealthItem']],['app/plan/assumptions.tsx',['addAssumption']],['app/plan/currency/page.tsx',['addFxRate','setDisplayCurrency']],['app/plan/goals.tsx',['createGoal']],['app/plan/spending/page.tsx',['saveSpendingPlan']]];
for(const[p,names]of forms){let s=read(p);const crlf=s.includes('\r\n');s=s.replace(/\r\n/g,'\n');
 for(const n of names){
  let at;while((at=s.indexOf(`<form action={${n}}`))>=0){
   const close=(()=>{let d=0,re=/<form\b|<\/form>/g;re.lastIndex=at;let m;while((m=re.exec(s))){if(m[0]==='<form'){d++}else{d--;if(d===0)return m.index}}throw new Error('no close '+p)})();
   s=s.slice(0,close)+'</SafeForm>'+s.slice(close+7);
   s=s.slice(0,at)+`<SafeForm action={${n}Safely}`+s.slice(at+`<form action={${n}}`.length);
  }
  const imp=new RegExp(`\\b${n}\\b(?=[^\\n]*from "[^"]*actions")`);if(!imp.test(s))throw new Error('import '+n+' '+p);
  // keep any other use, add the safe name beside it
  s=s.replace(imp,s.split(n).length>2?`${n}, ${n}Safely`:`${n}Safely`);
 }
 const first=s.match(/^import [^\n]*\n/m);s=s.replace(first[0],first[0]+'import { SafeForm } from "@/components/safe-form";\n');
 writeFileSync(p,crlf?s.replace(/\n/g,'\r\n'):s);console.log('ok',p)}

