import postgres from "postgres";
import { createClient } from "@supabase/supabase-js";
const apply = process.argv.includes("--apply");
const db = postgres(process.env.SUPABASE_DB_URL, { max: 1, onnotice() {} });
const admin = createClient(process.env.NEXT_PUBLIC_SUPABASE_URL, process.env.SUPABASE_SERVICE_ROLE_KEY, { auth: { persistSession: false, autoRefreshToken: false } });
const keep = new Set(["e2e-auth", "artifact-film-demo"]);
const users = (await db`select u.id, u.email, u.raw_user_meta_data->>'qa_test' qa, (select id from public.workspaces w where w.owner_id=u.id limit 1) ws
  from auth.users u where (u.email like '%@example.invalid' or u.email like '%@example.test') and u.raw_user_meta_data->>'qa_test' is not null`).filter(u => !keep.has(u.qa));
console.log("marked disposable users", users.length);
if (apply) {
  let removed = 0; const failed = {};
  for (const user of users) {
    try {
      if (user.ws) for (const bucket of ["imports", "chat"]) {
        const listed = await admin.storage.from(bucket).list(user.ws, { limit: 1000 });
        if (listed.data?.length) await admin.storage.from(bucket).remove(listed.data.map(file => `${user.ws}/${file.name}`));
      }
      await db.begin(async tx => {
        await tx`select set_config('request.jwt.claim.sub', ${user.id}, true)`;
        await tx`select public.delete_account()`;
      });
      removed += 1;
    } catch (cause) { const key = String(cause.message).slice(0, 110); failed[key] = (failed[key] ?? 0) + 1; }
  }
  console.log("removed", removed, "failed", failed);
}
console.log("left", (await db`select count(*)::int n from auth.users where email like '%@example.invalid' or email like '%@example.test'`)[0].n, "total users", (await db`select count(*)::int n from auth.users`)[0].n);
await db.end({ timeout: 2 });

